import test from "node:test";
import assert from "node:assert/strict";
import { createApp } from "./app.js";

async function setup() { let now = Date.parse("2030-01-01T07:40:00+08:00"); const app = createApp({ exposeCaptchaCode: true, clock: () => now }); await new Promise((resolve) => app.listen(0, resolve)); return { app, base: `http://127.0.0.1:${app.address().port}`, setNow: (v) => { now = Date.parse(v); }, close: () => new Promise((resolve) => app.close(resolve)) }; }
async function json(base, path, options = {}) { const response = await fetch(base + path, { headers: { "content-type": "application/json", ...(options.headers ?? {}) }, ...options, body: options.body && JSON.stringify(options.body) }); return { response, body: response.status === 204 ? null : await response.json() }; }
async function login(base, identifier, role, browser) { await json(base, "/api/v1/auth/register", { method: "POST", body: { identifier, password: "correct horse", role } }); const c = await json(base, "/api/v1/auth/captcha", { method: "POST", body: { browserId: browser } }); const l = await json(base, "/api/v1/auth/login", { method: "POST", body: { identifier, password: "correct horse", browserId: browser, challengeId: c.body.challengeId, captcha: c.body.code } }); return l.body.accessToken; }

test("clinical room supports authorized materials, messages, immutable result and append-only correction", async (t) => {
  const r = await setup(); t.after(r.close); const admin = await login(r.base, "admin-clinical@example.test", "admin", "admin-clinical"); await json(r.base, "/api/v1/auth/register", { method: "POST", body: { identifier: "doctor-clinical@example.test", password: "correct horse", role: "doctor" } }); const d = await json(r.base, "/api/v1/admin/departments", { method: "POST", headers: { authorization: `Bearer ${admin}` }, body: { name: "皮肤科" } }); const doc = await json(r.base, "/api/v1/admin/doctors", { method: "POST", headers: { authorization: `Bearer ${admin}` }, body: { identifier: "doctor-clinical@example.test", departmentId: d.body.department.id } }); await json(r.base, `/api/v1/admin/doctors/${doc.body.doctor.id}/certify`, { method: "POST", headers: { authorization: `Bearer ${admin}` }, body: { certified: true } }); const s = await json(r.base, "/api/v1/admin/schedules", { method: "POST", headers: { authorization: `Bearer ${admin}` }, body: { doctorId: doc.body.doctor.id, departmentId: d.body.department.id, date: "2030-01-01", halfDay: "AM", mode: "ONLINE", capacity: 1 } }); const patient = await login(r.base, "patient-clinical@example.test", "patient", "patient-clinical"); const hold = await json(r.base, "/api/v1/bookings/holds", { method: "POST", headers: { authorization: `Bearer ${patient}` }, body: { scheduleId: s.body.schedule.id } }); await json(r.base, `/api/v1/bookings/${hold.body.appointment.id}/pay`, { method: "POST", headers: { authorization: `Bearer ${patient}` }, body: {} }); const materials = await json(r.base, `/api/v1/clinical/appointments/${hold.body.appointment.id}/materials`, { method: "POST", headers: { authorization: `Bearer ${patient}` }, body: { text: "皮肤发痒两天", attachments: [{ filename: "report.pdf", contentType: "application/pdf", size: 1000 }] } }); assert.equal(materials.response.status, 201); const invalid = await json(r.base, `/api/v1/clinical/appointments/${hold.body.appointment.id}/materials`, { method: "POST", headers: { authorization: `Bearer ${patient}` }, body: { attachments: [{ filename: "bad.exe", contentType: "application/octet-stream", size: 5 }] } }); assert.equal(invalid.response.status, 400);
  r.setNow("2030-01-01T08:00:00+08:00"); const doctor = await login(r.base, "doctor-clinical@example.test", "doctor", "doctor-clinical"); const latePatient = await login(r.base, "patient-clinical@example.test", "patient", "patient-clinical-late"); const checked = await json(r.base, `/api/v1/reception/check-in/${hold.body.appointment.id}`, { method: "POST", headers: { authorization: `Bearer ${latePatient}` }, body: {} }); const called = await json(r.base, "/api/v1/reception/call-next", { method: "POST", headers: { authorization: `Bearer ${doctor}` }, body: { scheduleId: s.body.schedule.id } }); const started = await json(r.base, `/api/v1/clinical/appointments/${hold.body.appointment.id}/start`, { method: "POST", headers: { authorization: `Bearer ${doctor}` }, body: {} }); assert.equal(started.body.encounter.status, "IN_SERVICE"); const message = await json(r.base, `/api/v1/clinical/appointments/${hold.body.appointment.id}/messages`, { method: "POST", headers: { authorization: `Bearer ${latePatient}` }, body: { text: "请问需要注意什么" } }); assert.equal(message.response.status, 201); const result = await json(r.base, `/api/v1/clinical/appointments/${hold.body.appointment.id}/result`, { method: "POST", headers: { authorization: `Bearer ${doctor}` }, body: { text: "建议复诊" } }); assert.equal(result.body.result.readonly, true); const blocked = await json(r.base, `/api/v1/clinical/appointments/${hold.body.appointment.id}/result`, { method: "POST", headers: { authorization: `Bearer ${doctor}` }, body: { text: "覆盖" } }); assert.equal(blocked.response.status, 409); const correction = await json(r.base, `/api/v1/clinical/appointments/${hold.body.appointment.id}/corrections`, { method: "POST", headers: { authorization: `Bearer ${doctor}` }, body: { text: "补充说明" } }); assert.equal(correction.response.status, 201); const view = await json(r.base, `/api/v1/clinical/appointments/${hold.body.appointment.id}`, { headers: { authorization: `Bearer ${latePatient}` } }); assert.equal(view.body.result.text, "建议复诊"); assert.equal(view.body.corrections.length, 1);
});
